mapper.update:
UPDATE course_forum
SET title = #{title}, content = #{content}, updated_at = now()
WHERE id = #{id}

mapper.select:
SELECT cf.*, c.name AS courseName, u.fullname AS writerName, CASE WHEN f.table_id IS NOT NULL THEN TRUE ELSE FALSE END AS isAttached, IFNULL(cc.comment_count, 0) AS commentCount FROM course_forum cf JOIN course c ON cf.course_id = c.id JOIN `user` u ON cf.writer_id = u.id LEFT JOIN (SELECT DISTINCT table_id FROM file WHERE table_name = 'course_forum' AND deleted_at IS NULL) f ON cf.id = f.table_id LEFT JOIN (SELECT course_forum_id, COUNT(id) AS comment_count FROM course_forum_comment WHERE deleted_at IS NULL GROUP BY course_forum_id) cc ON cf.id = cc.course_forum_id
cf.deleted_at IS NULL
AND cf.course_id = #{courseId}
AND cf.course_id IN
#{item}
AND
OR cf.title LIKE CONCAT('%', #{keyword}, '%')
OR cf.content LIKE CONCAT('%', #{keyword}, '%')
OR u.fullname LIKE CONCAT('%', #{keyword}, '%')
AND (CASE WHEN f.table_id IS NOT NULL THEN TRUE ELSE FALSE END) = #{hasAttachment}
AND cf.course_id = #{courseId}
AND c.name = #{courseName}
ORDER BY cf.is_hotpost DESC,
cf.read_count cf.title cf.forum_like cf.created_at
ASC, DESC,
cf.id DESC LIMIT #{skip}, #{pagingSize}

SELECT COUNT(*) FROM course_forum cf JOIN course c ON cf.course_id = c.id JOIN `user` u ON cf.writer_id = u.id LEFT JOIN (SELECT DISTINCT table_id FROM file WHERE table_name = 'course_forum' AND deleted_at IS NULL) f ON cf.id = f.table_id
cf.deleted_at IS NULL
AND cf.course_id = #{courseId}
AND cf.course_id IN
#{item}
AND
OR cf.title LIKE CONCAT('%', #{keyword}, '%')
OR cf.content LIKE CONCAT('%', #{keyword}, '%')
OR u.fullname LIKE CONCAT('%', #{keyword}, '%')
AND (CASE WHEN f.table_id IS NOT NULL THEN TRUE ELSE FALSE END) = #{hasAttachment}
AND cf.course_id = #{courseId}
AND c.name = #{courseName}

mapper.update:
UPDATE course_forum_comment
SET deleted_at = NOW()
WHERE id = #{commentId}
